CREATE DATABASE IF NOT EXISTS nesta CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nesta;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE properties (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT NOT NULL,city VARCHAR(100) NOT NULL,address VARCHAR(190) NOT NULL,price DECIMAL(14,2) NOT NULL,area DECIMAL(8,2) NOT NULL,rooms TINYINT UNSIGNED NOT NULL,type VARCHAR(50) NOT NULL,image VARCHAR(500) NOT NULL,status ENUM('active','draft') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(city),INDEX(price));
CREATE TABLE favorites (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,property_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY user_property(user_id,property_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(property_id) REFERENCES properties(id) ON DELETE CASCADE);
